import itertools
def count(m, xs):
    return sum(1 for a in itertools.product(range(1, m + 1), repeat=len(xs)) if all(x == 0 or x == v for x, v in zip(xs, a)) and all(abs(p - q) <= 1 for p, q in zip(a, a[1:])))
def fast(m, xs):
    w = [0] * (m + 2)
    for v in range(1, m + 1): w[v] = 1 if xs[0] in (0, v) else 0
    for x in xs[1:]:
        w = [0] + [(w[v - 1] + w[v] + w[v + 1]) if x in (0, v) else 0 for v in range(1, m + 1)] + [0]
    return sum(w)
result = count(5, (2, 0, 2))

